function plant(event) {
    const x = player.x;
    const y = player.y;
    if (tiles[x + ',' + y] === undefined) {
        tiles[x + ',' + y] = { crop: 'seed', stage: 0 };
        inventory.seeds--;
        draw();
    }
}

function grow(event) {
    const x = player.x;
    const y = player.y;
    if (tiles[x + ',' + y] !== undefined && tiles[x + ',' + y].crop === 'seed' && tiles[x + ',' + y].stage < 3) {
        tiles[x + ',' + y].stage++;
        if (tiles[x + ',' + y].stage === 3) {
            tiles[x + ',' + y].crop = 'crop';
            inventory.crops++;
        }
        draw();
    }
}

canvas.addEventListener('keydown', movePlayer);
canvas.addEventListener('keydown', plant);
canvas.addEventListener('keydown', grow);

// Increment 3: harvesting.
// h harvests a crop from the player's tile: tiles['x,y'] = { crop: 'crop', stage: 3 } and crops go up by one.
// h must be able to harvest only one crop at a time.
// h must be able to harvest only from tiles that are currently grown at stage 3.
// Harvested crops are drawn. Arrow-key movement and everything already working must keep working.
function harvest(event) {
    const x = player.x;
    const y = player.y;
    if (tiles[x + ',' + y] !== undefined && tiles[x + ',' + y].crop === 'crop' && tiles[x + ',' + y].stage === 3) {
        tiles[x + ',' + y] = undefined;
        inventory.crops++;
        draw();
    }
}

canvas.addEventListener('keydown', harvest);

